import{_ as n,l,o as e,c as i,v as t,p as s,x as r,d,i as h,S as p}from"./chunks/framework.InCnrqk-.js";const u=JSON.parse('{"title":"选择第 k 小","description":"","frontmatter":{"title":"选择第 k 小","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/select-kth.md","filePath":"cs/select-kth.md","lastUpdated":1789023840000}'),c={name:"cs/select-kth.md"};function k(B,a,T,E,A,m){const o=l("Mermaid");return e(),i("div",null,[a[1]||(a[1]=t('<h1 id="选择第-k-小" tabindex="-1">选择第 k 小 <a class="header-anchor" href="#选择第-k-小" aria-label="Permalink to &quot;选择第 k 小&quot;">​</a></h1><div class="epigraph"><p>只要第 $k$ 小，不必排出全部次序；随机分区期望线性，最坏线性要五数取中那样的保证轴。</p><footer>—— 据 Hoare, 1961；Blum, Floyd, Pratt, Rivest and Tarjan, Time Bounds for Selection, 1973；CLRS 第 9 章整理</footer></div><p>上一课<a href="/cs/radix-bucket">基数与桶</a>在整数键上排完全表。本课不重做计数。缺口是：比较模型里全排序仍有 \\(\\Omega(n\\log n)\\) 墙，但<strong>只问第 \\(k\\) 小</strong>信息量小得多。本课交出随机选择（期望线性）与最坏线性选择的存在，不把全表排序当子程序。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>一次分区后，轴的秩 \\(q\\) 已知。若 \\(k=q\\) 结束；若 \\(k\\lt q\\) 只递归左段，否则把 \\(k\\) 改成 \\(k-q\\) 递归右段。与快排不同：只走一侧。期望仍由随机轴给出 \\(T(n)\\le T(\\)均匀子规模\\()+\\Theta(n)\\)，解为 \\(\\Theta(n)\\)。最坏仍可平方——与快排同一退化。</p><p>缺口因此不是新的分区，而是<strong>单侧递归</strong>把期望从 \\(n\\log n\\) 降到线性。全排序下界管不了选择：决策树只须区分「谁是第 \\(k\\)」，不是 \\(n!\\) 个全排列。</p><h3 id="五数取中不是默认实现" tabindex="-1">五数取中不是默认实现 <a class="header-anchor" href="#五数取中不是默认实现" aria-label="Permalink to &quot;五数取中不是默认实现&quot;">​</a></h3><p>BFPRT：每五元组取中位数，再递归选这些中位数的中位数当轴，保证两侧都丢掉常数比例，最坏 \\(T(n)=T(n/5)+T(7n/10)+O(n)=\\Theta(n)\\)。常数大，教学上证明最坏线性存在即可。主干实现仍是随机选择。</p><p><span class="marginnote">Hoare 的 FIND 即随机选择。Blum 等 1973 给出最坏线性。本课两者都点名：一个用，一个证明墙对选择是 \\(\\Theta(n)\\) 量级可及。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>随机：<code>partition</code>，比较 \\(k\\) 与轴秩，单侧递归。期望线性；高概率也线性，本课不写浓度不等式。最坏线性：保证轴后同样单侧，主定理式的递推用替换法。</p>',11)),(e(),s(p,null,{default:r(()=>[h(o,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22n%20%E4%B8%AA%E9%94%AE%EF%BC%8C%E8%A6%81%E7%AC%AC%20k%20%E5%B0%8F%22%5D%20--%3E%20PART%5B%22%E5%88%86%E5%8C%BA%E5%BE%97%E8%BD%B4%E7%A7%A9%20q%22%5D%0A%20%20PART%20--%3E%20EQ%5B%22k%3Dq%EF%BC%9A%E7%BB%93%E6%9D%9F%22%5D%0A%20%20PART%20--%3E%20L%5B%22k%EF%BC%9Cq%EF%BC%9A%E5%8F%AA%E8%B5%B0%E5%B7%A6%22%5D%0A%20%20PART%20--%3E%20R%5B%22k%3Eq%EF%BC%9A%E5%8F%AA%E8%B5%B0%E5%8F%B3%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>下界：每个键至少要被看过，故 \\(\\Omega(n)\\)。与上界同阶（随机期望或 BFPRT 最坏）。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>选择是后课算法的零件：中位数作轴、统计量、BFPRT 自己的递归。图算法不在这里；最短路不是选第 \\(k\\) 小边。也不把堆建成再弹 \\(k\\) 次当成最优：那是 \\(n+k\\log n\\)， \\(k\\) 大时不如线性选择。</p><p>整数键上当然可以先计数再找第 \\(k\\)，那是上一课模型，本课强调比较模型里也能线性。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不排完。不处理同时找多个顺序统计量的最优常数。多选问题、在线选择都不进主干。图与串从下一课开始，选择作为数组上的收尾。</p><p>后课默认：第 \\(k\\) 小期望 \\(\\Theta(n)\\) 比较；最坏线性存在。数组算法到此；图上的遍历是下一缺口。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>选择只走分区的一侧，期望线性。</li><li>全排序下界不管选择；选择本身 \\(\\Omega(n)\\)。</li><li>BFPRT 证明最坏线性，常数大。</li><li>出处：Hoare, FIND；Blum et al., 1973；CLRS 第 9 章。</li></ul>',9))])}const f=n(c,[["render",k]]);export{u as __pageData,f as default};
